        done text;
BEGIN
  PERFORM pg_advisory_xact_lock(20261127,61);
  INSERT INTO schema_migrations(version) VALUES('2026-11-27-calculated-catalog-offers')
    ON CONFLICT(version) DO NOTHING RETURNING version INTO done;
  IF done IS NULL THEN RETURN; END IF;
  UPDATE shared_addons t
    SET list_price=(x.value->>0)::numeric,initial_price=(x.value->>0)::numeric,
        discount_percent=0,description=x.value->>1,
        name=CASE WHEN t.code='hosting' THEN 'استضافة ويب مُدارة' ELSE t.name END,
        unit_label=CASE WHEN t.code='hosting' THEN 'حساب / سنة' ELSE t.unit_label END,
        initial_unit_label=CASE WHEN t.code='hosting' THEN 'حساب / سنة' ELSE t.initial_unit_label END
    FROM jsonb_each(a) x WHERE t.code=x.key AND t.is_active AND t.pricing_type=x.value->>2;
  UPDATE packages t
    SET list_price=(x.value->>0)::numeric,initial_price=(x.value->>0)::numeric,
        discount_percent=0,description=x.value->>1,features=x.value->2,updated_at=now()
    FROM jsonb_each(p) x WHERE t.id=x.key::uuid AND t.deleted_at IS NULL AND NOT t.is_custom_quote;
  INSERT INTO product_ownership_prices(scope,owner_key,mode,list_price,initial_price,discount_percent)
    SELECT 'package',t.id::text,'copy',t.list_price,t.list_price,0
    FROM packages t WHERE p ? t.id::text AND t.deleted_at IS NULL AND NOT t.is_custom_quote
  ON CONFLICT(scope,owner_key,mode) DO UPDATE
    SET list_price=EXCLUDED.list_price,initial_price=EXCLUDED.initial_price,discount_percent=0;

  PERFORM 1 FROM site_pages WHERE slug='catalog' AND locale='ar' FOR UPDATE;
  UPDATE site_pages t SET content=jsonb_set(t.content,'{items}',(
    SELECT coalesce(jsonb_agg(CASE WHEN s ? (i.value->>'slug')
      AND coalesce(i.value->>'published','true')='true' AND coalesce(i.value->>'archived','false')='false'
      THEN i.value || jsonb_build_object('basePrice',(s->(i.value->>'slug')->>0)::numeric,
        'description',s->(i.value->>'slug')->>1,'features',s->(i.value->>'slug')->2,
        'modules',s->(i.value->>'slug')->2,'note',s->(i.value->>'slug')->>3,
        'includedAddonCodes',s->(i.value->>'slug')->4)
      ELSE i.value END ORDER BY i.ordinality),'[]'::jsonb)
    FROM jsonb_array_elements(t.content->'items') WITH ORDINALITY i(value,ordinality)
  ),false), updated_at=now()
  WHERE t.slug='catalog' AND t.locale='ar' AND jsonb_typeof(t.content->'items')='array';
  INSERT INTO product_ownership_prices(scope,owner_key,mode,list_price,initial_price,discount_percent)
    SELECT 'sector',i->>'slug','copy',(s->(i->>'slug')->>0)::numeric,(s->(i->>'slug')->>0)::numeric,0
    FROM site_pages t CROSS JOIN LATERAL jsonb_array_elements(t.content->'items') i
    WHERE t.slug='catalog' AND t.locale='ar' AND s ? (i->>'slug')
      AND coalesce(i->>'published','true')='true' AND coalesce(i->>'archived','false')='false'
  ON CONFLICT(scope,owner_key,mode) DO UPDATE
    SET list_price=EXCLUDED.list_price,initial_price=EXCLUDED.initial_price,discount_percent=0;
END;
$tariff$;

-- Keep the shared list intact without selling the content panel twice.
CREATE OR REPLACE FUNCTION skip_included_package_addon() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.package_id='33333333-3333-4333-8333-333333333333'::uuid AND NEW.code='admin_dashboard' THEN
    NEW.is_active=false;
    NEW.is_required=false;
  END IF;
  RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS skip_included_package_addon ON package_options;
CREATE TRIGGER skip_included_package_addon BEFORE INSERT OR UPDATE ON package_options FOR EACH ROW EXECUTE FUNCTION skip_included_package_addon();
UPDATE package_options SET is_active=false,is_required=false
  WHERE package_id='33333333-3333-4333-8333-333333333333'::uuid AND code='admin_dashboard' AND (is_active OR is_required);
